class AccountTest {
    private Account account;

    @BeforeEach
    void setUp() { account = new Account(100); }   // Arrange

    @Test
    void withdrawWithinBalanceReducesBalance() {
        boolean ok = account.withdraw(30);          // Act
        assertThat(ok).isTrue();                    // Assert
        assertThat(account.balance()).isEqualTo(70);
    }
}
